  function overview(c){const x=overallCompany(c);if(!x)return '';const posts=state.posts.get(c.service_id)||[];const eliteRecent=window.PROP_ORDINARY_EVIDENCE_V222?window.PROP_ORDINARY_EVIDENCE_V222.renderSection([...posts].sort((a,b)=>String(b.date||'').localeCompare(String(a.date||''))).slice(0,6),'ko',window.PROP_DETAIL_UI?.excerpts||{}):'';return `<section class="panel"><h3>종합 참고 점수</h3><strong class="trial-big">${Number(x.overall).toFixed(2)} / 100</strong>${simpleComponents(c)}<p>출금·계정 보고 50%, X 본인 후기 20%, 운영 기반 30%를 결합한 비교 지표입니다. 실제 출금 성공률이나 안전 확률이 아닙니다.</p><button type="button" data-tab="events">본인 보고와 출처 보기 →</button></section>${eliteRecent}`;}

