    const filtered=newestReportFirst(posts).filter(matches),months=[...new Set(posts.map(reportMonth).filter(Boolean))].sort().reverse();
    const options=[['problems',"수익 감액·거절·BAN"],['received','출금 수령'],['refused','출금 거절'],['ban_or_closed','이용 금지 / 계정 정지'],['profit_reduced','수익 감액'],['delayed','출금 지연']];
    const cards=filtered.slice(0,state.visible).map(p=>`<article class="phase15-event-card"><div><time>${esc(reportDisplayDate(p))}</time><div class="phase15-event-meta">${(p.labels||[]).map(id=>`<span class="event-chip">${esc(labels[id]||id)}</span>`).join('')}</div></div><div>${(p.labels||[]).filter(id=>reportMatchesType({labels:[id]},selected)).map(id=>{const url=p.category_source_links?.[id];return url?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(labels[id]||id)}: 원문 ↗</a>`:`<span>원문 미확인</span>`}).join(' ')}</div></article>`).join('');
    return `<section class="panel"><h3>본인 출금·계정 보고</h3><p>일반 게시물의 본인 보고만 표시합니다. 이용자의 주장으로, 거래 사실을 독립적으로 검증한 결과는 아닙니다. 하나의 보고에 여러 유형이 포함될 수 있습니다.</p><p class="section-note">최신 게시물 순(UTC). 처음에는 수익 감액·거절·BAN/계정 정지만 표시합니다. 유형을 바꾸면 다른 보고도 볼 수 있습니다.</p><div class="automatic-filters"><label>유형<select data-event-type><option value="">전체</option>${options.map(([v,l])=>`<option value="${v}"${selected===v?' selected':''}>${l}</option>`).join('')}</select></label><label>월<select data-event-month><option value="">전체</option>${months.map(m=>`<option value="${m}"${month===m?' selected':''}>${m}</option>`).join('')}</select></label><span>${number(filtered.length)}건</span></div><div class="phase15-event-list">${cards||'<p>해당 보고가 없습니다.</p>'}</div>${filtered.length>state.visible?'<button class="link-button" data-more>더 보기</button>':''}</section>`;
