  function detailHeroLogo(c){try{const origin=new URL(c.links.official,location.href).origin;const cached=approvedBrandLogos[c.service_id]||`https://www.google.com/s2/favicons?sz=128&domain_url=${encodeURIComponent(origin)}`;return `<span class="detail-brand-logo" aria-hidden="true"><img src="${esc(cached)}" alt="" loading="lazy" referrerpolicy="no-referrer"></span>`}catch(_){return `<span class="detail-brand-logo"><span>${esc((c.company_name||'P').slice(0,1))}</span></span>`}}
  function renderDetail(){const c=state.data.companies.find(x=>x.service_id===state.selected)||state.data.companies[0];state.selected=c.service_id;if(window.PROP_ORDINARY_EVIDENCE_V222&&!state.posts.has(c.service_id)&&!state.ordinaryEvidenceLoading){state.ordinaryEvidenceLoading=true;loadPosts(c).then(()=>{state.ordinaryEvidenceLoading=false;renderDetail()}).catch(()=>{state.ordinaryEvidenceLoading=false})}$('#company-select').value=c.service_id;const content={overview:overview(c)+window.foundation194(c.service_id),evidence:evidence(c),monthly:monthly(c),events:events(c),plans:planPanel(c)}[state.tab];$('#detail-root').innerHTML=`${c.service_id==="icfunded-fx-cfd"?"<p class=\"section-note\">소수 표본: 후기 점수에 사용된 자료는 2개 계정의 게시물 2개이며, 출금·문제의 본인 보고는 1건입니다. 출금 점수는 공통 사전 보정값의 영향을 크게 받습니다.</p>":""}<div class="detail-hero-card"><div class="detail-hero-main">${detailHeroLogo(c)}<div class="detail-hero-copy"><h3>${esc(c.company_name)}</h3><p>${market(c)} · 본인 보고 기간 2024-09-23–${esc(c.weekly_score_reference_date||'2026-10-04')}</p></div></div><div class="detail-hero-actions"><a class="link-button" href="${esc(c.links.official)}" target="_blank" rel="noopener noreferrer">공식 사이트 ↗</a><a class="link-button affiliate" href="/${lang}/report/?company=${encodeURIComponent(c.service_id)}">후기 제보</a></div></div><div class="detail-tabs"><button type="button" data-tab="overview" data-detail-tab="overview" aria-selected="${state.tab==='overview'}">${T.overview}</button><button type="button" data-tab="evidence" data-detail-tab="evidence" aria-selected="${state.tab==='evidence'}">${T.evidence}</button><button type="button" data-tab="monthly" data-detail-tab="monthly" aria-selected="${state.tab==='monthly'}">${T.monthly}</button><button type="button" data-tab="events" data-detail-tab="events" aria-selected="${state.tab==='events'}">${T.eventTab}</button><button type="button" data-tab="plans" data-detail-tab="plans" aria-selected="${state.tab==='plans'}">플랜·규칙</button></div><div class="detail-panel">${content}</div>`}
  function bind(){document.addEventListener('click',e=>{const tab=e.target.closest('[data-tab]');if(tab){state.tab=tab.dataset.tab;renderDetail();return}const open=e.target.closest('[data-open-events]');if(open){state.selected=open.dataset.openEvents;state.tab='events';state.visible=20;renderDetail();location.hash='detail';return}const range=e.target.closest('[data-range]');if(range){state.monthlyView=range.dataset.range;renderDetail();return}const month=e.target.closest('[data-month]');if(month){state.monthlySelected=month.dataset.month;renderDetail();return}if(e.target.closest('[data-more]')){state.visible+=20;renderDetail()}});document.addEventListener('change',e=>{if(e.target.id==='company-select'){state.selected=e.target.value;state.monthlySelected=null;state.eventStatus='main';state.eventType='problems';state.eventMonth='';state.visible=20;renderDetail()}else if(e.target.id==='market-filter'){state.market=e.target.value;renderComparison()}else if(e.target.id==='sort-order'){state.sort=e.target.value;renderComparison()}else if(e.target.matches('[data-event-status]')){state.eventStatus=e.target.value;state.visible=20;renderDetail()}else if(e.target.matches('[data-event-type]')){state.eventType=e.target.value;state.visible=20;renderDetail()}else if(e.target.matches('[data-event-month]')){state.eventMonth=e.target.value;state.visible=20;renderDetail()}});$('#company-search').addEventListener('input',e=>{state.query=e.target.value.trim().toLowerCase();renderComparison()});document.querySelectorAll('[data-comparison-tab]').forEach(b=>b.addEventListener('click',()=>{document.querySelector('#comparison-table').dataset.mobileColumn=b.dataset.comparisonTab;document.querySelectorAll('[data-comparison-tab]').forEach(x=>x.setAttribute('aria-selected',String(x===b)))}))}
  async function init(){try{const [data,ai,ordinary,overall,tags,complaints,complaintTendency]=await Promise.all([window.pcDataRequest('/preview.json').then(r=>r.json()),window.pcDataRequest('/public_ja_v1/ai-classification-summary.json').then(r=>r.json()),window.pcDataRequest('/data/normal-report-ratios-v143.json').then(r=>r.json()),window.pcDataRequest('/data/overall-reference-v194.json').then(r=>r.json()),window.pcDataRequest('/data/tag-badges-v194.json').then(r=>r.json()),window.pcDataRequest('/candidate-v85/complaint-summary-v1.json').then(r=>r.json()),window.pcDataRequest('/data/complaint-tendency-v1.json').then(r=>r.json())]);state.data=data;state.ai=ai;state.complaints=complaints;state.complaintTendency=complaintTendency;state.byName=new Map(ai.companies.map(x=>[x.display_name,x]));state.ordinaryByService=new Map((ordinary.companies||[]).map(x=>[x.service_id,x]));state.overallByService=new Map((overall.companies||[]).map(x=>[x.service_id,x]));state.complaintByService=new Map(Object.entries(complaints.companies||{}));state.complaintTendencyByService=new Map(Object.entries(complaintTendency.companies||{}));state.tagByService=new Map(Object.entries(tags.companies||{}));state.selected=document.body.dataset.initialCompany||new URLSearchParams(location.search).get('company')||data.companies[0].service_id;const tab=new URLSearchParams(location.search).get('tab');if(['overview','evidence','monthly','events','plans'].includes(tab))state.tab=tab;$('#publication-scope-grid').innerHTML=`<article><strong>${number(ai.totals.collection.collected)}</strong><span>${T.collected}</span></article><article><strong>${number(ai.totals.classification.complete)}</strong><span>${T.classified}</span></article><article><strong>${number(ai.totals.scope.related)}</strong><span>${T.related}</span></article><article><strong>${number(ai.totals.event_counts.main_active_posts)}</strong><span>${T.events}</span></article>`;$('#featured-grid').innerHTML=data.companies.filter(x=>x.featured).map(featuredMarkup).join('');$('#company-select').innerHTML=data.companies.map(x=>`<option value="${esc(x.service_id)}">${esc(x.company_name)}</option>`).join('');const markets=[...new Set(data.companies.map(x=>x.market_label))];$('#market-filter').innerHTML=`<option value="">${T.marketAll}</option>${markets.map(x=>`<option value="${esc(x)}">${market({market_label:x})}</option>`).join('')}`;if($('#sort-order'))$('#sort-order').value=state.sort;state.viewMode='normal';document.querySelectorAll('[data-view-mode]').forEach(b=>{b.setAttribute('aria-pressed',String(b.dataset.viewMode===state.viewMode));b.addEventListener('click',()=>{state.viewMode=b.dataset.viewMode;localStorage.setItem('propcheckViewMode',state.viewMode);document.querySelectorAll('[data-view-mode]').forEach(x=>x.setAttribute('aria-pressed',String(x.dataset.viewMode===state.viewMode)));renderComparison()})});state.query=($('#company-search')?.value||'').trim().toLowerCase();renderComparison();renderDetail();bind()}catch(error){console.error(error);$('#detail-root').textContent=T.loadError}}
  /* v60 overview redesign override */
  const V60={overviewTitle:'회사 종합 평가',updated:'기준일',scoreLabel:'종합 참고 점수',summaryHigh:'전체적으로 상당히 안정감이 있는 편입니다.',summaryMid:'후보로 남기기 쉬운, 균형형 회사입니다.',summaryLow:'강점과 약점을 나눠서 확인하고 싶은 회사입니다.',summaryFallback:'저장된 데이터와 공개 정보를 바탕으로 특징을 정리했습니다.',summaryDescHigh:'출금, 이용자 후기, 투명성의 균형이 전반적으로 높은 편입니다.',summaryDescMid:'큰 약점이 적고 전체적인 균형을 보며 판단하기 쉬운 회사입니다. 출금 항목이 특히 강하고 다른 항목도 무난한 수준입니다.',summaryDescLow:'항목별 차이가 있어 종합 점수만 보지 말고 강점과 약점을 따로 확인하는 편이 좋습니다.',summaryDescFallback:'종합 참고 점수와 항목별 점수를 나란히 보여 회사의 성격을 쉽게 파악할 수 있게 했습니다.',compTitle:'평가 내역',compNote:'항목별 점수 (100점 만점)',payout:'출금 가능성',experience:'X 본인 후기',external:'다른 매체와의 일치',transparency:'운영 기반',mini:'종합 참고 점수는 실제 출금 성공률이나 안전 확률이 아닙니다. 일반 게시물의 본인 보고, 저장된 후기, 다른 매체와의 일치, 운영 기반을 따로 요약한 참고 지표입니다.',transTitle:'투명성 메모',checked:'확인 완료',partial:'일부 확인',pending:'미확인',transFallback:'투명성 평가는 계약 상대, 규정, 지급 이력, 수입/비용, 가용 자금, 권한의 6개 항목을 같은 기준으로 정리합니다.'};
  function v60Ring(val,label){const pct=Math.max(0,Math.min(100,Number(val||0)));return `<div class="detail-v60-ring" style="--pct:${pct}%"><div class="detail-v60-ring-inner"><small>${esc(label)}</small><strong>${Number(pct).toFixed(1)}</strong><span>/ 100</span></div></div>`}
  function v60Headline(x){const s=Number(x?.overall||0);if(s>=80)return V60.summaryHigh;if(s>=65)return V60.summaryMid;if(s>0)return V60.summaryLow;return V60.summaryFallback}
  function v60Desc(x){const s=Number(x?.overall||0);if(s>=80)return V60.summaryDescHigh;if(s>=65)return V60.summaryDescMid;if(s>0)return V60.summaryDescLow;return V60.summaryDescFallback}
  function v60Rows(c){const x=overallCompany(c)||{},rows=[[V60.payout,x.payout_account],[V60.experience,x.experience],['운영 기반',x.transparency]];return `<div class="detail-v60-list">${rows.map(([l,v])=>{const n=Math.max(0,Math.min(100,Number(v||0)));return `<div class="detail-v60-row"><b>${esc(l)}</b><div class="detail-v60-track"><i style="width:${n}%"></i></div><span class="detail-v60-val">${Number(v||0).toFixed(2)}</span></div>`}).join('')}</div>`}
  function overview(c){const x=overallCompany(c);if(!x)return '';const posts=state.posts.get(c.service_id)||[];const eliteRecent=window.PROP_ORDINARY_EVIDENCE_V222?window.PROP_ORDINARY_EVIDENCE_V222.renderSection([...posts].sort((a,b)=>String(b.date||'').localeCompare(String(a.date||''))).slice(0,6),'ko',window.PROP_DETAIL_UI?.excerpts||{}):'';return `<section class="panel"><h3>종합 참고 점수</h3><strong class="trial-big">${Number(x.overall).toFixed(2)} / 100</strong>${simpleComponents(c)}<p>출금·계정 보고 50%, X 본인 후기 20%, 운영 기반 30%를 결합한 비교 지표입니다. 실제 출금 성공률이나 안전 확률이 아닙니다.</p><button type="button" data-tab="events">본인 보고와 출처 보기 →</button></section>${eliteRecent}`;}

  let planData={};
let planChoice={category:'',currency:'',capital:''};
function visiblePlan(p){return !p.display_excluded&&p.initial_capital!=null&&!!p.capital_currency&&![16666,33333,66666,133333,266666].includes(Number(p.initial_capital));}
function capitalKey(p){return `${p.capital_currency==='USD_display'?'USD':p.capital_currency} ${p.initial_capital}`;}
function amountLabel(value,currency){if(value===null||value===undefined||value==='')return '미확인';const n=Number(value);if(!Number.isFinite(n))return esc(value);const f=x=>x.toLocaleString('ko',{maximumFractionDigits:6});if(currency==='JPY')return `${f(n/10000)}만 엔`;if(currency==='USD'||currency==='USD_display')return n%1000===0?`$${f(n/1000)}K`:`$${f(n)}`;return `${esc(currency||'통화 미확인')} ${f(n)}`;}
function priceLabel(value,currency){if(value==null||value===''||!currency)return '—';const c=currency==='USD_display'?'USD':currency;return esc(c||'통화 미확인')+' '+esc(Number.isFinite(Number(value))?Number(value).toLocaleString('ko',{maximumFractionDigits:6}):value);}
function planActive(){return Object.values(planChoice).some(Boolean);}
function matchingPlans(id){return (planData[id]||[]).filter(visiblePlan).filter(p=>(!planChoice.category||p.category===planChoice.category)&&(!planChoice.currency||capitalKey(p).startsWith(planChoice.currency+' '))&&(!planChoice.capital||capitalKey(p)===planChoice.capital));}
function planPrice(p){return `${esc(p.plan_name)} ／ ${amountLabel(p.initial_capital,p.capital_currency)} ／ 게시 가격 <b>${priceLabel(p.display_price,p.price_currency)}</b>`;}
function planPrices(id){const ps=matchingPlans(id),n=new Set(ps.map(p=>p.plan_name)).size;const preview=planChoice.capital?ps.slice(0,2).map(p=>'<div class="plan-price-group-v168"><strong class="plan-price-name-v168">'+esc(p.plan_name)+'</strong><span>'+priceLabel(p.display_price,p.price_currency)+'</span></div>').join(''):'';return '<span class="plan-price-count-v168">해당 플랜: '+n+'</span>'+preview+'<button type="button" class="plan-expand-v169" aria-haspopup="dialog" aria-expanded="false">플랜·가격·주요 규칙 보기 ↗</button>';}
function ruleValue(v){if(v==null||v==='')return '미확인';if(Array.isArray(v))return v.length?v.map(ruleValue).join(' / '):'미확인';if(typeof v==='object')return esc(JSON.stringify(v));return esc(({static:'고정',trailing:'추적형',true:'가능',false:'불가'})[String(v)]??v);}
function percentValue(v){return v==null?'미확인':Array.isArray(v)?v.map(x=>ruleValue(x)+'%').join(' → '):ruleValue(v)+'%';}
function planMatrix(id){
 const lifted=document.querySelector("#detail-root")?commonRuleData200(id).common:[];
 const groups=new Map();matchingPlans(id).forEach(p=>{const key=p.plan_name+'|'+capitalKey(p).split(' ')[0];if(!groups.has(key))groups.set(key,[]);groups.get(key).push(p);});
 const fields=[['비용(게시 가격)','price'],['수익 목표(평가)','profit_target'],['최대 DD·계산법','max_dd'],['일일 DD·계산법','daily_dd'],['합격 후 구매비 환급','refund_after_pass'],['합격 후 수익 목표','funded_profit_target'],['최대 Lot','max_lots'],['EA·자동 매매','ea'],['복사 거래','copy'],['VPS 제한','vps'],['IP 규칙','ip'],['최소 수익일','minimum_profit_days'],['수익 배분','profit_share'],['출금 신청 간격','payout_interval'],['출금 상한·최소액','payout_limit'],['레버리지','leverage'],['일관성 규칙','consistency']];
 const renderCell=(f,key)=>{if(!f)return '<span class="plan-omitted-v174" aria-label="미기재. 제한 없음의 의미가 아닙니다">—</span>';const text=esc(f.text_ko);const refs=f.sources.filter(s=>s.source_url.startsWith('https://'));const amount=key==='price'?f.text_ko.match(/(?:USDC|USD|JPY|EUR|GBP)\s*[0-9,]+(?:\.[0-9]+)?/):null;const content=amount?'<strong class="plan-price-main-v174">'+esc(amount[0])+'</strong><details class="plan-price-terms-v174"><summary>비용 조건</summary><p>'+text+'</p></details>':'<div class="plan-rule-text-v174">'+text+'</div>';return content+(refs.length?'<details class="plan-citation-v174"><summary>근거·확인일</summary>'+refs.map((s,i)=>'<a href="'+esc(s.source_url)+'" target="_blank" rel="noopener noreferrer">공식 '+(i+1)+' ↗</a> <time>'+esc(s.checked_on)+'</time>').join('<br>')+'</details>':'');};
 return [...groups].map(([_,rows])=>{rows.sort((a,b)=>a.initial_capital-b.initial_capital);const name=rows[0].plan_name;let body='';for(const [label,key] of fields){if(lifted.includes(key))continue;const vals=rows.map(p=>p.approved_display?.[key]||null);if(vals.every(v=>!v))continue;const same=vals.every(v=>JSON.stringify(v)===JSON.stringify(vals[0]));body+='<tr'+(key==='price'?' class="plan-fee-v169"':'')+'><th scope="row">'+label+'</th>'+(same?'<td colspan="'+rows.length+'">'+renderCell(vals[0],key)+'</td>':vals.map(v=>'<td>'+renderCell(v,key)+'</td>').join(''))+'</tr>';}
 return '<section class="plan-family-v169"><h4>'+esc(name)+'</h4>'+officialPlanNotice(rows)+'<p class="plan-scroll-hint-v174">자금 규모별 비교표 <span>← 좌우로 스크롤 →</span></p><div class="plan-matrix-scroll-v169" tabindex="0" role="region" aria-label="'+esc(name)+' 자금 규모별 조건표"><table class="plan-matrix-v169" style="min-width:'+Math.max(600,160+rows.length*185)+'px!important"><thead><tr><th scope="col">초기 자금</th>'+rows.map(p=>'<th scope="col">'+amountLabel(p.initial_capital,p.capital_currency)+'</th>').join('')+'</tr></thead><tbody>'+body+'</tbody></table></div>'+(document.querySelector('#detail-root')?'':specialRules(rows))+'</section>';}).join('')||'<p>이 조건에 해당하는 게시 플랜이 없습니다.</p>';
}

function officialPlanNotice(rows){
 const prices=[...new Set(rows.map(p=>p.source_url))].filter(u=>typeof u==='string'&&u.startsWith('https://'));
 const rules=[...new Set(rows.flatMap(p=>[...(p.rule_source_urls||[]),...(p.display_rule_sources||[]).map(s=>s.source_url),...(p.special_rules||[]).map(s=>s.source_url)]))].filter(u=>typeof u==='string'&&u.startsWith('https://'));
 const links=(urls,label)=>urls.map((u,i)=>'<a href="'+esc(u)+'" target="_blank" rel="noopener noreferrer">'+label+(urls.length>1?' '+(i+1):'')+' ↗</a>').join(' ・ ');
 return '<div class="plan-official-notice-v172"><strong>반드시 공식 페이지에서 최신 1차 정보를 확인하세요.</strong><p>조건·요금은 변경될 수 있습니다.</p><div>'+links(prices,'공식 가격 출처')+'</div>'+(rules.length?'<details><summary>공식 규칙·근거 페이지('+rules.length+')</summary><div>'+links(rules,'공식 규칙·근거')+'</div></details>':'')+'</div>';
}
function specialRules(rows){const special=[...new Map(rows.flatMap(p=>p.special_rules||[]).map(x=>[x.title+x.text,x])).values()];if(!special.length)return '';return '<aside class="plan-special-v170"><h5>특수 규칙·리스크 주의</h5>'+special.map(x=>'<p><strong>'+esc(x.title)+'</strong><br>'+esc(x.text)+(x.source_url?'<br><a href="'+esc(x.source_url)+'" target="_blank" rel="noopener noreferrer">공식 규칙 ↗</a> <small>확인 '+esc(x.checked_on)+'</small>':'')+'</p>').join('')+'</aside>';}

function planNote(){return '<p class="plan-filter-note-v168">가격은 조사 시점 기준으로 합격 후 비용·세금·할인 포함 최종 총액과 다를 수 있습니다. 근거를 확인한 조건만 기재합니다. 미기재·“—”는 제한 없음을 뜻하지 않습니다. DD 계산법과 평가·합격 후 차이를 확인하세요. 좌우 스크롤로 자금별 비교가 가능합니다.</p>';}
const fullPlanCompanies=new Set();
async function togglePlanRow(row){
 const button=row.querySelector('.plan-expand-v169');
 const sid=row.dataset.companyId;
 if(!fullPlanCompanies.has(sid)){
   if(button.disabled)return;
   const label=button.textContent;button.disabled=true;button.textContent="\ubd88\ub7ec\uc624\ub294 \uc911\u2026";
   try{planData[sid]=await window.pcLoadCompanyPlans("ko",sid);fullPlanCompanies.add(sid);}
   catch(e){button.title="\ud50c\ub79c\uc744 \ubd88\ub7ec\uc624\uc9c0 \ubabb\ud588\uc2b5\ub2c8\ub2e4. \ub2e4\uc2dc \uc2dc\ub3c4\ud574 \uc8fc\uc138\uc694.";button.textContent="\ud50c\ub79c\uc744 \ubd88\ub7ec\uc624\uc9c0 \ubabb\ud588\uc2b5\ub2c8\ub2e4. \ub2e4\uc2dc \uc2dc\ub3c4\ud574 \uc8fc\uc138\uc694.";button.disabled=false;return;}
   button.textContent=label;button.disabled=false;
   if(!row.isConnected)return;
 }
 if(document.querySelector('.plan-modal-v171'))return;
 const modal=document.createElement('dialog');modal.className='plan-modal-v171';modal.setAttribute('aria-labelledby','plan-modal-title-v171');
 modal.innerHTML='<header class="plan-modal-head-v171"><div><h3 id="plan-modal-title-v171">플랜·가격·주요 규칙</h3><p>닫으면 원래 업체 목록으로 돌아갑니다</p></div><button type="button" class="plan-modal-close-v171" aria-label="플랜 표 닫기" autofocus>×</button></header><div class="plan-modal-body-v171">'+planNote()+planMatrix(row.dataset.companyId)+'</div>';
 document.body.appendChild(modal);
 const oldOverflow=document.body.style.overflow;document.body.style.overflow='hidden';button.setAttribute('aria-expanded','true');
 modal.addEventListener('close',()=>{document.body.style.overflow=oldOverflow;button.setAttribute('aria-expanded','false');modal.remove();button.focus({preventScroll:true});},{once:true});
 modal.querySelector('.plan-modal-close-v171').onclick=()=>modal.close();
 modal.addEventListener('click',event=>{if(event.target===modal){const r=modal.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)modal.close();}});
 modal.showModal();
}


function commonRuleData200(id){
 const rows=(planData[id]||[]).filter(visiblePlan), keys=['ea','copy','vps','ip'];
 const common=keys.filter(k=>rows.length&&rows.every(p=>p.approved_display?.[k])&&rows.every(p=>JSON.stringify(p.approved_display[k])===JSON.stringify(rows[0].approved_display[k])));
 return {rows,common};
}
function commonRules200(id){
 const {rows,common}=commonRuleData200(id);if(!rows.length)return '';
 const esc200=esc, t=["공통 규칙·금지 사항", "놓치기 쉬운 특별 규칙", "게재 플랜의 공통 조건입니다. 평가/펀디드 단계 및 옵션 예외는 각 항목을 확인하세요.", "공식 근거", "확인", "대상 플랜"], labels=["EA·자동매매", "카피 거래", "VPS 제한", "IP 규칙"],keys=['ea','copy','vps','ip'];
 const refs=x=>(x.sources||[]).map(s=>'<a target="_blank" rel="noopener noreferrer" href="'+esc200(s.source_url)+'">'+t[3]+' ↗</a> <small>'+t[4]+' '+esc200(s.checked_on)+'</small>').join(' · ');
 let s=common.length?'<section class="common-rules-v200"><h4>'+t[0]+'</h4><p>'+t[2]+'</p><dl>'+common.map(k=>{const x=rows[0].approved_display[k];return '<div><dt>'+labels[keys.indexOf(k)]+'</dt><dd>'+esc200(x.text_ko)+'<p>'+refs(x)+'</p></dd></div>';}).join('')+'</dl></section>':'';
 const groups=new Map();rows.forEach((p,index)=>(p.special_rules||[]).forEach(x=>{const key=x.title+x.text; if(!groups.has(key))groups.set(key,{x,names:new Set(),indices:new Set()});groups.get(key).names.add(p.plan_name);groups.get(key).indices.add(index);}));
 if(groups.size)s+='<section class="special-rules-v200"><h4>'+t[1]+'</h4>'+[...groups.values()].map(({x,names,indices})=>'<details class="legacy-special-v203"><summary>'+esc200(x.title)+'</summary><p>'+esc200(x.text)+'</p><small>'+t[5]+': '+(indices.size===rows.length ? "게재 전체 플랜(단계·옵션 조건은 본문 참조)" : [...names].map(esc200).join(' / '))+'</small><p><a target="_blank" rel="noopener noreferrer" href="'+esc200(x.source_url)+'">'+t[3]+' ↗</a> <small>'+t[4]+' '+esc200(x.checked_on)+'</small></p></details>').join('')+'</section>';
 return s;
}


